package com.eventos.api.entity;
import javax.persistence.*; import java.time.LocalDate;
@Entity @Table(name="events") public class Event { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false) private String name; @Column(nullable=false) private LocalDate date; @Column(nullable=false) private String location; @Column(length=2000) private String imageUrl; @ManyToOne(optional=false,fetch=FetchType.LAZY) @JoinColumn(name="admin_id") private Admin admin; public Long getId(){return id;} public String getName(){return name;} public LocalDate getDate(){return date;} public String getLocation(){return location;} public String getImageUrl(){return imageUrl;} public Admin getAdmin(){return admin;} public void setName(String v){name=v;} public void setDate(LocalDate v){date=v;} public void setLocation(String v){location=v;} public void setImageUrl(String v){imageUrl=v;} public void setAdmin(Admin v){admin=v;} }
